{"hypotheses": [
  {
    "name": "Capital Efficiency + Underreaction in High Volatility",
    "mechanism": "Combining Cash Productivity (CashProd) and Analyst EPS Forecast Revisions (AnalystRevision) leverages persistent underreaction to improvements in capital efficiency, especially during periods of high investor uncertainty reflected by elevated VIX. Elevated volatility amplifies mispricing due to slower incorporation of positive efficiency signals.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": 1.0, "primitive": "AnalystRevision"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.95,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Intangible Value + Operating Leverage Defensive",
    "mechanism": "Combining Intangible-adjusted Book-to-Market (IntanBM) and Operating Leverage (OPLeverage) generates alpha by capturing firms whose asset-light innovative models are undervalued and resilient to downturns, with the effect amplified in negative market regimes as defensive characteristics are rewarded.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanBM"},
        {"weight": 1.0, "primitive": "OPLeverage"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Earnings Consistency + Off-Season Reversal",
    "mechanism": "Firms with consistent earnings, when combined with off-season long-term reversal effects, exploit market overreaction to stale information. Off-season reversal helps capture delayed mean-reversion after periods of excessive pessimism or optimism, especially in large firms with analyst coverage.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsConsistency"},
        {"weight": 0.5, "primitive": "MomOffSeason06YrPlus"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "MomOffSeason06YrPlus", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Shareholder Activism and Low Net Equity Financing",
    "mechanism": "Pairing measures of active shareholder engagement (Activism2) with low Net Equity Finance (NetEquityFinance) identifies firms under pressure to improve capital allocation while not diluting shareholders, combining governance-driven value creation with conservative financial policy.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Activism2"},
        {"weight": -1.0, "primitive": "NetEquityFinance"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.90,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Asset Growth Anomaly + Idiosyncratic Volatility",
    "mechanism": "Mixing Asset Growth (AssetGrowth) and idiosyncratic volatility (IdioVol3F) exploits investor overextrapolation and mispricing in high-growth, high-volatility stocks, where behavioral biases are most acute and limits to arbitrage are greatest.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "IdioVol3F"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.92,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Cash Flow Valuation Gap Arbitrage",
    "mechanism": "Combining Cash flow to market (CF) with negative Book Leverage (BookLeverage) identifies underleveraged companies that are undervalued on a cash flow basis, thus targeting balance sheet strength and fundamental mispricing unaddressed by either factor alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CF"},
        {"weight": -1.0, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "BookLeverage", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.88,
    "expected_decay_half_life_months": 28
  },
  {
    "name": "R&D Leaders with Positive Customer Momentum",
    "mechanism": "Firms that invest heavily in R&D (RD) and simultaneously benefit from positive customer momentum (iomom_cust) achieve outsized returns due to synergistic innovation and demand-driven growth, especially powerful in emerging markets where innovation diffusion is more rapid.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": 0.5, "primitive": "iomom_cust"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "RD", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.87,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Share Repurchases + Earnings Forecast Disagreement",
    "mechanism": "Stocks with high share repurchases (ShareRepurchase) and elevated analyst forecast dispersion (ForecastDispersion) outperform as repurchases signal management confidence during times of market uncertainty and investor disagreement, exploiting underappreciated buyback signaling effects.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "ShareRepurchase", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.94,
    "expected_decay_half_life_months": 20
  }
]}
